from __future__ import annotations

from enum import Enum


class CheckKind(Enum):
    """Kinds of checks performed on a package change.

    The value is the lowercase serialized form used in JSON output and in the
    rendered comment placeholders.
    """

    CI_UPLOAD = "ci_upload"
    RELEASE_PIPELINE = "release_pipeline"
    REPO_PUBLIC = "repo_public"
    PR_LINK = "pr_link"


class CheckStatus(Enum):
    """Possible outcomes of a single check."""

    PASS = "pass"
    WARN = "warn"
    FAIL = "fail"
    NEEDS_AGENT = "needs_agent"


class CheckResult:
    """Result of a single check."""

    def __init__(self, status: CheckStatus, details: str) -> None:
        """Initialize a check result."""
        self.status = status
        self.details = details

    def to_dict(self) -> dict:
        """Return a JSON-serializable representation."""
        return {"status": self.status.value, "details": self.details}

    def __repr__(self) -> str:
        """Return a debug representation."""
        return f"CheckResult(status={self.status!r}, details={self.details!r})"


class PackageChange:
    """A single package version change detected in a diff."""

    def __init__(
        self,
        name: str,
        old_version: str | None,
        new_version: str,
        checks: dict[CheckKind, CheckResult] | None = None,
        repo_url: str | None = None,
    ) -> None:
        """Initialize a package change."""
        self.name = name
        self.old_version = old_version
        self.new_version = new_version
        self.checks: dict[CheckKind, CheckResult] = checks if checks is not None else {}
        self.repo_url = repo_url

    @property
    def needs_agent(self) -> bool:
        """Return True if any check requires agent follow-up."""
        return any(
            result.status is CheckStatus.NEEDS_AGENT for result in self.checks.values()
        )

    def to_dict(self) -> dict:
        """Return a JSON-serializable representation."""
        return {
            "name": self.name,
            "old_version": self.old_version,
            "new_version": self.new_version,
            "repo_url": self.repo_url,
            "needs_agent": self.needs_agent,
            "checks": {
                kind.value: result.to_dict() for kind, result in self.checks.items()
            },
        }

    def __repr__(self) -> str:
        """Return a debug representation."""
        return (
            f"PackageChange(name={self.name!r}, old_version={self.old_version!r}, "
            f"new_version={self.new_version!r})"
        )


class CheckRunResult:
    """Aggregated result of running all checks for a PR."""

    def __init__(
        self, pr_number: int, packages: list[PackageChange] | None = None
    ) -> None:
        """Initialize a check run result."""
        self.pr_number = pr_number
        self.packages: list[PackageChange] = packages if packages is not None else []

    @property
    def needs_agent(self) -> bool:
        """Return True if any package requires agent follow-up."""
        return any(package.needs_agent for package in self.packages)

    def _per_kind_needs_agent(self) -> dict[str, bool]:
        """Return, per check kind, whether any package needs the agent for it."""
        result: dict[str, bool] = {}
        for kind in CheckKind:
            result[kind.value] = any(
                (check := package.checks.get(kind)) is not None
                and check.status is CheckStatus.NEEDS_AGENT
                for package in self.packages
            )
        return result

    def to_dict(self) -> dict:
        """Return a JSON-serializable representation of the whole run."""
        # Imported lazily to avoid a circular import at module load time.
        from .render import render_comment

        per_kind = self._per_kind_needs_agent()
        data: dict = {
            "pr_number": self.pr_number,
            "needs_agent": self.needs_agent,
            "rendered_comment": render_comment(self),
            "checks": per_kind,
            "packages": [package.to_dict() for package in self.packages],
        }
        # Also expose each check kind as a top-level key (e.g. "repo_public").
        data.update(per_kind)
        return data

    def __repr__(self) -> str:
        """Return a debug representation."""
        return (
            f"CheckRunResult(pr_number={self.pr_number!r}, "
            f"packages={self.packages!r})"
        )
