from __future__ import annotations

import fnmatch
import os
import re

from .models import PackageChange

# Files whose changes we track. Matched against the basename of the path.
_TRACKED_PATTERN = "requirements*.txt"

# Matches ``name==version`` (optionally with extras), e.g. ``Foo_Bar[extra]==1.2``.
_REQUIREMENT_RE = re.compile(
    r"^(?P<name>[A-Za-z0-9][A-Za-z0-9._-]*)(?:\[[^\]]*\])?\s*==\s*(?P<version>[^\s;,]+)"
)


def _normalize_name(name: str) -> str:
    """Normalize a package name per PEP 503."""
    return re.sub(r"[-_.]+", "-", name).lower()


def _strip_path_prefix(path: str) -> str:
    """Strip a leading ``a/`` or ``b/`` git diff prefix from a path."""
    path = path.strip()
    # Diff paths may carry a trailing tab-separated timestamp; drop it.
    path = path.split("\t", 1)[0].strip()
    if path.startswith(("a/", "b/")):
        return path[2:]
    return path


def _is_tracked(path: str) -> bool:
    """Return True if the given path is a tracked requirements file."""
    if not path or path == "/dev/null":
        return False
    basename = os.path.basename(_strip_path_prefix(path))
    return fnmatch.fnmatch(basename, _TRACKED_PATTERN)


def _parse_requirement(text: str) -> tuple[str, str] | None:
    """Parse a requirement line into ``(normalized_name, version)``.

    Returns ``None`` for comment lines, blank lines and lines without a
    pinned ``==`` version. Inline comments are stripped.
    """
    # Strip inline comments (and full comment lines).
    if "#" in text:
        text = text.split("#", 1)[0]
    text = text.strip()
    if not text:
        return None
    match = _REQUIREMENT_RE.match(text)
    if not match:
        return None
    return _normalize_name(match.group("name")), match.group("version")


def parse_diff(diff_text: str) -> list[PackageChange]:
    """Parse a unified diff into a list of :class:`PackageChange` objects.

    Only changes in files matching ``requirements*.txt`` are considered.
    Lines without a version change, comment lines and inline comments are
    ignored. Package names are normalized per PEP 503.
    """
    removed: dict[str, str] = {}
    added: dict[str, str] = {}
    order: list[str] = []

    tracked = False
    pending_old_path: str | None = None

    for line in diff_text.splitlines():
        if line.startswith("--- "):
            pending_old_path = line[4:]
            continue
        if line.startswith("+++ "):
            new_path = line[4:]
            # Prefer the new path; fall back to the old path for deletions.
            path = new_path
            if _strip_path_prefix(new_path) in ("", "/dev/null"):
                path = pending_old_path or new_path
            tracked = _is_tracked(path)
            pending_old_path = None
            continue
        if line.startswith(("diff ", "index ", "@@", "rename ", "similarity ")):
            continue
        if not tracked:
            continue

        if line.startswith("+") and not line.startswith("+++"):
            parsed = _parse_requirement(line[1:])
            if parsed is not None:
                name, version = parsed
                added[name] = version
                if name not in order:
                    order.append(name)
        elif line.startswith("-") and not line.startswith("---"):
            parsed = _parse_requirement(line[1:])
            if parsed is not None:
                name, version = parsed
                removed[name] = version

    changes: list[PackageChange] = []
    for name in order:
        new_version = added[name]
        old_version = removed.get(name)
        if old_version == new_version:
            # No effective version change.
            continue
        changes.append(
            PackageChange(
                name=name,
                old_version=old_version,
                new_version=new_version,
                checks={},
            )
        )
    return changes
