from __future__ import annotations

from urllib.parse import urlparse

import requests

_TIMEOUT = 30

# Hostnames considered known code hosts. Matched exactly against the URL
# hostname (which urlparse already lowercases and strips of any port).
_KNOWN_CODE_HOSTS = frozenset(
    {"github.com", "gitlab.com", "www.github.com", "www.gitlab.com"}
)

# Keys in ``project_urls`` that are preferred when looking for a repo URL.
_PREFERRED_REPO_KEYS = ("Source", "Repository")


class PypiPackageInfo:
    """Information fetched from PyPI for a specific package version."""

    def __init__(
        self,
        project_urls: dict,
        repo_url: str | None,
        file_provenance_urls: list[str],
        found: bool,
    ) -> None:
        """Initialize the package info."""
        self.project_urls = project_urls
        self.repo_url = repo_url
        self.file_provenance_urls = file_provenance_urls
        self.found = found

    def __repr__(self) -> str:
        """Return a debug representation."""
        return (
            f"PypiPackageInfo(found={self.found!r}, repo_url={self.repo_url!r}, "
            f"file_provenance_urls={self.file_provenance_urls!r})"
        )


class ProvenanceResult:
    """Result of a provenance/attestation check."""

    def __init__(
        self,
        has_attestation: bool,
        publisher_kind: str | None,
        recognized_publisher: bool,
        detail: str,
    ) -> None:
        """Initialize the provenance result."""
        self.has_attestation = has_attestation
        self.publisher_kind = publisher_kind
        self.recognized_publisher = recognized_publisher
        self.detail = detail

    def __repr__(self) -> str:
        """Return a debug representation."""
        return (
            f"ProvenanceResult(has_attestation={self.has_attestation!r}, "
            f"publisher_kind={self.publisher_kind!r}, "
            f"recognized_publisher={self.recognized_publisher!r})"
        )


def _clean(value: str | None) -> str | None:
    """Strip backtick and newline characters from a string."""
    if value is None:
        return None
    return value.replace("`", "").replace("\r", "").replace("\n", "")


def _get_json(url: str) -> tuple[object | None, int | None]:
    """Fetch and decode JSON from ``url``.

    Returns ``(data, status_code)``. ``data`` is ``None`` on network errors,
    non-200 responses, or invalid JSON. ``status_code`` is ``None`` only for
    network-level errors.
    """
    try:
        response = requests.get(
            url, timeout=_TIMEOUT, headers={"Accept": "application/json"}
        )
    except requests.RequestException:
        return None, None
    status = response.status_code
    if status != 200:
        return None, status
    try:
        return response.json(), status
    except ValueError:
        return None, status


def _is_code_host_url(url: object) -> bool:
    """Return True if ``url`` points to a known code host by exact hostname."""
    if not isinstance(url, str):
        return False
    try:
        hostname = urlparse(url).hostname
    except ValueError:
        return False
    return hostname in _KNOWN_CODE_HOSTS


def _extract_repo_url(project_urls: dict) -> str | None:
    """Select a repository URL from ``project_urls``.

    Prefers the ``Source``/``Repository`` keys, then scans all values for a
    URL hosted on a known code host. Rejects domain-suffix lookalikes and
    query-string matches. Returns ``None`` if nothing valid is found.
    """
    if not isinstance(project_urls, dict):
        return None

    for key in _PREFERRED_REPO_KEYS:
        if key in project_urls and _is_code_host_url(project_urls[key]):
            return _clean(project_urls[key])

    for value in project_urls.values():
        if _is_code_host_url(value):
            return _clean(value)

    return None


def _parse_versioned_data(data: dict, name: str, version: str) -> PypiPackageInfo:
    """Build a :class:`PypiPackageInfo` from a successful versioned response."""
    info = data.get("info") or {}
    project_urls = info.get("project_urls") or {}
    repo_url = _extract_repo_url(project_urls)

    file_provenance_urls: list[str] = []
    files = data.get("urls") or []
    if files:
        filename = files[0].get("filename")
        if filename:
            file_provenance_urls = [
                f"https://pypi.org/integrity/{name}/{version}/{filename}/provenance"
            ]

    return PypiPackageInfo(
        project_urls=project_urls,
        repo_url=repo_url,
        file_provenance_urls=file_provenance_urls,
        found=True,
    )


def fetch_package_info(name: str, version: str) -> PypiPackageInfo:
    """Fetch package metadata from PyPI for ``name`` at ``version``."""
    versioned_url = f"https://pypi.org/pypi/{name}/{version}/json"
    latest_url = f"https://pypi.org/pypi/{name}/json"

    data, status = _get_json(versioned_url)
    if status == 200 and isinstance(data, dict):
        return _parse_versioned_data(data, name, version)

    # The versioned endpoint failed (404, 5xx, network error, invalid JSON).
    # Fall back to the latest endpoint for project metadata only.
    latest_data, latest_status = _get_json(latest_url)
    if latest_status == 200 and isinstance(latest_data, dict):
        info = latest_data.get("info") or {}
        project_urls = info.get("project_urls") or {}
        return PypiPackageInfo(
            project_urls=project_urls,
            repo_url=_extract_repo_url(project_urls),
            file_provenance_urls=[],
            found=False,
        )

    # Both endpoints failed.
    return PypiPackageInfo(
        project_urls={}, repo_url=None, file_provenance_urls=[], found=False
    )


