from __future__ import annotations

from .diff import parse_diff
from .models import CheckKind, CheckResult, CheckRunResult, CheckStatus, PackageChange
from .pypi import check_provenance, fetch_package_info


def _checks_not_found(name: str, version: str) -> dict[CheckKind, CheckResult]:
    """Build checks for a package version that is not present on PyPI."""
    detail = f"{name}=={version} was not found on PyPI."
    return {
        CheckKind.CI_UPLOAD: CheckResult(CheckStatus.FAIL, detail),
        CheckKind.RELEASE_PIPELINE: CheckResult(CheckStatus.FAIL, detail),
        CheckKind.REPO_PUBLIC: CheckResult(CheckStatus.FAIL, detail),
        CheckKind.PR_LINK: CheckResult(CheckStatus.FAIL, detail),
    }


def _run_package_checks(change: PackageChange) -> None:
    """Fetch PyPI info and populate the checks for a single package change."""
    info = fetch_package_info(change.name, change.new_version)
    change.repo_url = info.repo_url

    if not info.found:
        change.checks = _checks_not_found(change.name, change.new_version)
        return

    provenance = check_provenance(info)
    checks: dict[CheckKind, CheckResult] = {}

    if provenance.recognized_publisher:
        checks[CheckKind.CI_UPLOAD] = CheckResult(
            CheckStatus.PASS,
            f"Uploaded with a PEP 740 attestation from {provenance.publisher_kind}.",
        )
        checks[CheckKind.RELEASE_PIPELINE] = CheckResult(
            CheckStatus.PASS,
            f"Released via a recognised publisher ({provenance.publisher_kind}).",
        )
    elif provenance.has_attestation:
        # Attestation present, but the publisher is not recognised.
        checks[CheckKind.CI_UPLOAD] = CheckResult(
            CheckStatus.WARN,
            "Uploaded with an attestation, but the publisher is not recognised.",
        )
        checks[CheckKind.RELEASE_PIPELINE] = CheckResult(
            CheckStatus.NEEDS_AGENT,
            "Attestation present but publisher unrecognised: "
            f"{provenance.publisher_kind!r}. Manual review needed.",
        )
    else:
        # No attestation at all.
        checks[CheckKind.CI_UPLOAD] = CheckResult(
            CheckStatus.WARN,
            f"No PEP 740 provenance attestation found. {provenance.detail}",
        )
        checks[CheckKind.RELEASE_PIPELINE] = CheckResult(
            CheckStatus.NEEDS_AGENT,
            "No attestation to confirm the release pipeline. Manual review needed.",
        )

    if info.repo_url is None:
        checks[CheckKind.REPO_PUBLIC] = CheckResult(
            CheckStatus.FAIL,
            f"{change.name} does not advertise a source repository on PyPI.",
        )
        checks[CheckKind.PR_LINK] = CheckResult(
            CheckStatus.FAIL,
            "No repository URL available, so the PR link cannot be verified.",
        )
    else:
        checks[CheckKind.REPO_PUBLIC] = CheckResult(
            CheckStatus.NEEDS_AGENT,
            f"Confirm the repository {info.repo_url} is public. Manual review needed.",
        )
        checks[CheckKind.PR_LINK] = CheckResult(
            CheckStatus.NEEDS_AGENT,
            "Confirm the change is backed by a linked pull request. "
            "Manual review needed.",
        )

    change.checks = checks


def run_checks(pr_number: int, diff_text: str) -> CheckRunResult:
    """Parse ``diff_text``, run all checks and return the aggregated result."""
    changes = parse_diff(diff_text)
    for change in changes:
        _run_package_checks(change)
    return CheckRunResult(pr_number=pr_number, packages=changes)
