from __future__ import annotations

from .models import CheckKind, CheckRunResult, CheckStatus, PackageChange

MARKER = "<!-- requirements-check -->"

_STATUS_EMOJI = {
    CheckStatus.PASS: "✅",
    CheckStatus.WARN: "⚠️",
    CheckStatus.FAIL: "❌",
}

_CHECK_TITLES = {
    CheckKind.CI_UPLOAD: "CI upload",
    CheckKind.RELEASE_PIPELINE: "Release pipeline",
    CheckKind.REPO_PUBLIC: "Repo public",
    CheckKind.PR_LINK: "PR link",
}


def _cell(package: PackageChange, kind: CheckKind) -> str:
    """Render the table cell for one package/check combination."""
    result = package.checks.get(kind)
    if result is None:
        return "—"
    if result.status is CheckStatus.NEEDS_AGENT:
        return f"{{{{CHECK_CELL:{package.name}:{kind.value}}}}}"
    return _STATUS_EMOJI.get(result.status, "")


def _detail(package: PackageChange, kind: CheckKind) -> str:
    """Render the detail bullet for one package/check combination."""
    title = _CHECK_TITLES[kind]
    result = package.checks.get(kind)
    if result is None:
        return f"- **{title}** — skipped."
    if result.status is CheckStatus.NEEDS_AGENT:
        return f"{{{{CHECK_DETAIL:{package.name}:{kind.value}}}}}"
    emoji = _STATUS_EMOJI.get(result.status, "")
    return f"- **{title}** {emoji} — {result.details}"


def _all_passed(result: CheckRunResult) -> bool:
    """Return True if every recorded check in every package passed."""
    if not result.packages:
        return False
    return all(
        check.status is CheckStatus.PASS
        for package in result.packages
        for check in package.checks.values()
    )


def render_comment(result: CheckRunResult) -> str:
    """Render a Markdown comment describing the check run."""
    lines: list[str] = [MARKER, "", "## Requirements supply-chain check", ""]

    if not result.packages:
        lines.append("No tracked requirement changes detected.")
        return "\n".join(lines)

    all_passed = _all_passed(result)
    if all_passed:
        lines.append("All requirements checks passed. ✅")
        lines.append("")

    kinds = list(CheckKind)
    details_tag = "<details open>" if result.needs_agent else "<details>"
    lines.append(details_tag)
    lines.append("<summary>Per-package results</summary>")
    lines.append("")

    # Summary table.
    header = "| Package | Change | " + " | ".join(
        _CHECK_TITLES[kind] for kind in kinds
    )
    header += " |"
    separator = "| --- " * (len(kinds) + 2) + "|"
    lines.append(header)
    lines.append(separator)
    for package in result.packages:
        change = (
            f"{package.old_version} → {package.new_version}"
            if package.old_version is not None
            else f"(new) {package.new_version}"
        )
        cells = [package.name, change]
        cells.extend(_cell(package, kind) for kind in kinds)
        lines.append("| " + " | ".join(cells) + " |")
    lines.append("")

    # Per-package detail bullets.
    for package in result.packages:
        lines.append(f"#### `{package.name}` ({package.new_version})")
        for kind in kinds:
            lines.append(_detail(package, kind))
        lines.append("")

    lines.append("</details>")
    return "\n".join(lines)
